package cn.yingxia.player.core

/** First pinyin letter for U+4E00..U+9FFF. A space means no initial. */
internal object PinyinInitials {
    private const val BASE = 0x4E00
    private const val TABLE = " dqdfmsd     xqbpfdwo  whlypcbjcc dmbzpbzz     z w   z    s     l       sl  z    lgtm    gd                     atn  hbltdzlatmmbj lx"

    fun of(text: String): String = buildString {
        var latin = false
        for (ch in text) {
            val cp = ch.code
            if (cp in BASE until BASE + TABLE.length) {
                val letter = TABLE[cp - BASE]
                if (letter != ' ') append(letter)
                latin = false
            } else if (ch in 'A'..'Z' || ch in 'a'..'z') {
                if (!latin) append(ch.lowercaseChar())
                latin = true
            } else latin = false
        }
    }
}
